&lt;p data-path-to-node="10"&gt;&lt;em data-path-to-node="10" data-index-in-node="0"&gt;Nice to Haves&lt;/em&gt;&lt;/p&gt;
&lt;ul data-path-to-node="11"&gt;
&lt;li&gt;
&lt;p id="p-rc_ed609c6a5ee7893e-265" data-path-to-node="11,0,0"&gt;&lt;span data-path-to-node="11,0,0,0"&gt;Practical experience writing Python for data engineering workloads&lt;/span&gt;&lt;span data-path-to-node="11,0,0,1"&gt;&lt;sup class="superscript"&gt;&lt;/sup&gt;&lt;/span&gt;&lt;span data-path-to-node="11,0,0,2"&gt;.&lt;/span&gt; &lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p id="p-rc_ed609c6a5ee7893e-266" data-path-to-node="11,1,0"&gt;&lt;span data-path-to-node="11,1,0,0"&gt;Experience working with modern cloud data warehouses, ideally Google BigQuery&lt;/span&gt;&lt;span data-path-to-node="11,1,0,1"&gt;&lt;sup class="superscript"&gt;&lt;/sup&gt;&lt;/span&gt;&lt;span data-path-to-node="11,1,0,2"&gt;.&lt;/span&gt; &lt;/p&gt;
